firestoreRules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAuthenticated() { return request.auth != null; }
    function isAdmin() { return isAuthenticated() && (request.auth.token.email == 'germainmensah1@gmail.com' || (exists(/databases/$(database)/documents/users/$(request.auth.uid)) && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin')); }
    function isOwner(userId) { return isAuthenticated() && request.auth.uid == userId; }
    match /users/{userId} { allow read: if true; allow create: if isOwner(userId) || isAdmin(); allow update: if (isOwner(userId) && (!request.resource.data.diff(resource.data).affectedKeys().hasAny(['role']) || isAdmin())) || isAdmin(); allow delete: if isAdmin(); }
    match /adminSummaries/{summaryId} { allow read, write: if isAdmin(); }
    match /deliveries/{deliveryId} { allow read: if true; allow create: if isAuthenticated() || (request.resource.data.trackingCode is string && request.resource.data.status is string); allow update: if isAuthenticated() || isAdmin() || (request.resource.data.status in ['assigned', 'picked_up', 'in_transit', 'approaching_300m', 'delivered', 'cancelled']); allow delete: if isAdmin(); }
    match /messages/{messageId} { allow read: if true; allow create: if (request.resource.data.content is string && request.resource.data.content.size() <= 1000 && request.resource.data.senderName is string); allow update, delete: if isAdmin() || (isAuthenticated() && resource.data.senderId == request.auth.uid); }
    match /aidRequests/{requestId} { allow read: if isAuthenticated() || isAdmin(); allow create: if isAuthenticated() && (request.resource.data.requestedAmount is number && request.resource.data.requestedAmount > 0 && request.resource.data.status == 'pending'); allow update: if isAdmin() || (isAuthenticated() && resource.data.driverId == request.auth.uid && resource.data.status == 'pending'); allow delete: if isAdmin(); }
    match /classifiedAds/{adId} { allow read: if true; allow create: if isAuthenticated() || (request.resource.data.title is string && request.resource.data.title.size() <= 200); allow update, delete: if isAdmin() || (isAuthenticated() && resource.data.authorId == request.auth.uid); }
    match /rentals/{rentalId} { allow read: if true; allow create: if isAuthenticated() || (request.resource.data.vehicleTitle is string); allow update, delete: if isAdmin() || (isAuthenticated() && resource.data.ownerId == request.auth.uid); }
    match /marketplace/{itemId} { allow read: if true; allow create: if isAuthenticated() || (request.resource.data.title is string); allow update, delete: if isAdmin() || (isAuthenticated() && resource.data.sellerId == request.auth.uid); }
    match /{document=**} { allow read, write: if false; }
  }
}
